css:
.horizon-sim-container {
    padding: 24px;
    background: #f4f5f7;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1a2744;
}
.horizon-sim-header {
    background: linear-gradient(135deg, #1a2744 0%, #2d3e5e 100%);
    color: #f4f5f7;
    padding: 28px 32px;
    border-radius: 4px;
    border-left: 6px solid #c9a961;
    margin-bottom: 20px;
}
.horizon-sim-brand-badge {
    font-size: 0.7rem;
    letter-spacing: 0.25em;
    color: #c9a961;
    margin-bottom: 8px;
    text-transform: uppercase;
    font-weight: 700;
}
.horizon-sim-header h1 {
    font-size: 1.65rem;
    font-weight: 700;
    margin: 0 0 6px 0;
    letter-spacing: 0.01em;
    color: #ffffff;
}
.horizon-sim-tagline {
    font-size: 0.95rem;
    color: #b8c2d0;
    margin: 0;
    font-style: italic;
}
.horizon-sim-period-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #d7dbe0;
    padding: 14px 20px;
    border-radius: 4px;
    margin-bottom: 18px;
}
.horizon-sim-period-main {
    font-weight: 700;
    color: #1a2744;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    font-size: 0.8rem;
}
.horizon-sim-period-title {
    color: #c9a961;
    font-weight: 700;
    font-size: 1rem;
    text-align: right;
}
.horizon-sim-gauges {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 14px;
    margin-bottom: 18px;
}
.horizon-sim-gauge {
    background: #ffffff;
    border: 1px solid #d7dbe0;
    border-top: 4px solid #1a2744;
    padding: 18px 20px;
    border-radius: 4px;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.horizon-sim-gauge:hover {
    box-shadow: 0 4px 14px rgba(26,39,68,0.08);
    transform: translateY(-2px);
}
.horizon-sim-gauge-profit { border-top-color: #2a7a4f; }
.horizon-sim-gauge-reputation { border-top-color: #b8860b; }
.horizon-sim-gauge-compass { border-top-color: #4a6fa5; }
.horizon-sim-gauge-label {
    font-size: 0.7rem;
    color: #6b7280;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    margin-bottom: 6px;
    font-weight: 600;
}
.horizon-sim-gauge-value {
    font-size: 1.85rem;
    font-weight: 700;
    color: #1a2744;
    line-height: 1.1;
}
.horizon-sim-gauge-sub {
    font-size: 0.72rem;
    color: #9aa3af;
    margin-top: 6px;
    font-style: italic;
}
.horizon-sim-greenwash-stamp {
    background: #c0392b;
    color: #ffffff;
    text-align: center;
    padding: 12px;
    font-weight: 800;
    letter-spacing: 0.22em;
    border-radius: 4px;
    margin-bottom: 18px;
    text-transform: uppercase;
    font-size: 0.9rem;
    border: 2px dashed #ffffff;
    animation: horizonPulse 1.2s ease-in-out;
}
@keyframes horizonPulse {
    0% { transform: scale(0.95); opacity: 0; }
    50% { transform: scale(1.02); opacity: 1; }
    100% { transform: scale(1); opacity: 1; }
}
.horizon-sim-briefing {
    background: #ffffff;
    border: 1px solid #d7dbe0;
    border-left: 4px solid #c9a961;
    padding: 20px 24px;
    border-radius: 4px;
    margin-bottom: 18px;
}
.horizon-sim-briefing-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.18em;
    color: #c9a961;
    margin-bottom: 10px;
    font-weight: 700;
}
.horizon-sim-briefing-text {
    color: #2a3952;
    font-size: 0.95rem;
    line-height: 1.6;
}
.horizon-sim-controls {
    background: #ffffff;
    border: 1px solid #d7dbe0;
    padding: 22px 24px;
    border-radius: 4px;
    margin-bottom: 18px;
}
.horizon-sim-decision-label {
    display: block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.18em;
    color: #1a2744;
    margin-bottom: 10px;
    font-weight: 700;
}
.horizon-sim-decision-select {
    width: 100%;
    background: #ffffff;
    border: 1px solid #c2c8d0;
    color: #1a2744;
    padding: 10px 12px;
    border-radius: 4px;
    font-size: 0.95rem;
    margin-bottom: 12px;
}
.horizon-sim-decision-select option {
    background: #ffffff;
    color: #1a2744;
}
.horizon-sim-decision-detail {
    background: #f4f5f7;
    border-left: 3px solid #4a6fa5;
    padding: 10px 14px;
    font-size: 0.85rem;
    color: #3a4a65;
    margin-bottom: 16px;
    min-height: 40px;
    border-radius: 0 4px 4px 0;
    line-height: 1.5;
}
.horizon-sim-button-row {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
}
.horizon-sim-submit {
    background: #1a2744;
    border: 1px solid #1a2744;
    color: #ffffff;
    font-weight: 600;
    padding: 10px 24px;
    border-radius: 4px;
    letter-spacing: 0.04em;
    transition: background 0.2s ease, color 0.2s ease;
}
.horizon-sim-submit:hover {
    background: #2d3e5e;
    border-color: #c9a961;
    color: #c9a961;
}
.horizon-sim-undo {
    border: 1px solid #c2c8d0;
    color: #5a6578;
    background: #ffffff;
    border-radius: 4px;
    padding: 8px 16px;
    font-size: 0.85rem;
}
.horizon-sim-stakeholders {
    background: #ffffff;
    border: 1px solid #d7dbe0;
    padding: 20px 24px;
    border-radius: 4px;
    margin-bottom: 18px;
}
.horizon-sim-stakeholder-heading {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.18em;
    color: #1a2744;
    margin-bottom: 12px;
    font-weight: 700;
}
.horizon-sim-stakeholder-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 10px;
}
.horizon-sim-stakeholder-card {
    background: #f4f5f7;
    border: 1px solid #e0e3e8;
    padding: 12px;
    border-radius: 4px;
    text-align: center;
}
.horizon-sim-sh-label {
    font-size: 0.7rem;
    color: #6b7280;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin-bottom: 6px;
    font-weight: 600;
}
.horizon-sim-sh-value {
    font-size: 0.95rem;
    font-weight: 700;
    color: #1a2744;
}
.horizon-sim-sh-value.sh-pos { color: #2a7a4f; }
.horizon-sim-sh-value.sh-neg { color: #c0392b; }
.horizon-sim-sh-value.sh-neu { color: #6b7280; }
.horizon-sim-history-wrap {
    background: #ffffff;
    border: 1px solid #d7dbe0;
    padding: 20px 24px;
    border-radius: 4px;
    margin-bottom: 18px;
}
.horizon-sim-history-heading {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.18em;
    color: #1a2744;
    margin-bottom: 12px;
    font-weight: 700;
}
.horizon-sim-history-table {
    font-size: 0.85rem;
    margin: 0;
}
.horizon-sim-history-table th {
    background: #1a2744;
    color: #c9a961;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-size: 0.7rem;
    border: none;
    padding: 10px 8px;
}
.horizon-sim-history-table td {
    padding: 8px;
    color: #2a3952;
    border-bottom: 1px solid #e0e3e8;
    vertical-align: middle;
}
.horizon-sim-chart-wrap {
    background: #ffffff;
    border: 1px solid #d7dbe0;
    padding: 20px;
    border-radius: 4px;
    height: 340px;
    margin-bottom: 18px;
}
@media (max-width: 768px) {
    .horizon-sim-container { padding: 14px; }
    .horizon-sim-gauges { grid-template-columns: 1fr; }
    .horizon-sim-stakeholder-grid { grid-template-columns: repeat(2, 1fr); }
    .horizon-sim-header h1 { font-size: 1.25rem; }
    .horizon-sim-period-bar { flex-direction: column; align-items: flex-start; gap: 6px; }
    .horizon-sim-period-title { text-align: left; }
}
/* v1.1.0 — completion debrief modal */
.ethics-sim-complete { text-align: center; padding: 8px 4px; color: #2a3142; }
.ethics-sim-complete-stars { font-size: 2rem; letter-spacing: 6px; color: #b8860b; }
.ethics-sim-complete-title { margin: 8px 0 2px; font-size: 0.95rem; color: #6b7280; text-transform: uppercase; letter-spacing: 1px; }
.ethics-sim-complete-score { font-size: 2.6rem; font-weight: 700; color: #4a6fa5; line-height: 1.1; }
.ethics-sim-complete-score .esc-max { font-size: 1rem; color: #9aa3b2; font-weight: 500; }
.ethics-sim-complete-tier { font-size: 1.1rem; margin: 4px 0 14px; color: #4a6fa5; font-weight: 600; }
.ethics-sim-complete-kpis { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin-bottom: 14px; }
.ethics-sim-complete-kpi { background: #f3f5f9; border-radius: 10px; padding: 10px 16px; min-width: 96px; }
.ethics-sim-complete-kpi .escc-val { display: block; font-size: 1.2rem; font-weight: 700; color: #2a3142; }
.ethics-sim-complete-kpi .escc-lbl { display: block; font-size: 0.72rem; color: #6b7280; margin-top: 2px; }
.ethics-sim-complete-insights-wrap { text-align: left; max-width: 560px; margin: 0 auto; }
.ethics-sim-complete-insights-wrap .esci-head { font-weight: 700; margin-bottom: 6px; }
.ethics-sim-complete-insights { margin: 0; padding-left: 20px; }
.ethics-sim-complete-insights li { margin-bottom: 6px; line-height: 1.4; }

