                { key: 'ignore',              labelKey: 'r4_opt_ig', detailKey: 'r4_det_ig', profit: 0,      reputation: -4, compass: -15, ethical: false, flag: 'coverup',
                  sh: { shareholders: 1, employees: -2, customers: 0, community: -1 } },
                { key: 'quiet_fix',           labelKey: 'r4_opt_qf', detailKey: 'r4_det_qf', profit: -10000, reputation: 0,  compass: -8,  ethical: false,
                  sh: { shareholders: 1, employees: -1, customers: 0, community: 0 } }
            ]
        },
        {
            id: 'csr_report',
            titleKey: 'r5_title',
            briefingKey: 'r5_brief',
            options: [
                { key: 'friedman',  labelKey: 'r5_opt_friedman',  detailKey: 'r5_det_friedman',  profit: 300000, reputation: -4, compass: -8, ethical: false,
                  sh: { shareholders: 2, employees: -1, customers: -1, community: -1 } },
                { key: 'balanced',  labelKey: 'r5_opt_balanced',  detailKey: 'r5_det_balanced',  profit: 0,      reputation: 4,  compass: 5,  ethical: true,
                  sh: { shareholders: 1, employees: 1, customers: 1, community: 1 } },
                { key: 'full_csr',  labelKey: 'r5_opt_fullcsr',   detailKey: 'r5_det_fullcsr',   profit: -200000,reputation: 10, compass: 18, ethical: true,
                  sh: { shareholders: -1, employees: 2, customers: 2, community: 2 } },
                { key: 'authentic', labelKey: 'r5_opt_authentic', detailKey: 'r5_det_authentic', profit: -80000, reputation: 8,  compass: 12, ethical: true,
                  sh: { shareholders: 0, employees: 2, customers: 2, community: 2 } }
            ]
        }
    ];

    const DELAYED = {
        greenwash:    { appliesInRound: 4, reputation: -10, compass: -12, stampKey: 'stamp_greenwash' },
        sourcing_risk:{ appliesInRound: 3, reputation: -5,  compass: -6,  stampKey: 'stamp_sourcing'  },
        coverup:      { appliesInRound: 5, reputation: -8,  compass: -10, stampKey: 'stamp_coverup'   }
    };

    class HorizonAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'The Ethical Compass';
            this.version = '1.1.0';
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    profit: 10000000,
                    reputation: 50,
                    compass: 0,
                    ethicalCount: 0,
                    unethicalCount: 0,
                    flags: {},
                    appliedDelays: {},
                    profitHistory: [],
                    reputationHistory: [],
                    compassHistory: [],
                    decisionHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = { choice: '' };
            }
            var self = this;
            setTimeout(function() { self._updateBriefing(state); }, 50);
        }

        _currentRound(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, ROUNDS.length - 1);
            return ROUNDS[idx];
        }

        _findOption(round, key) {
            for (var i = 0; i < round.options.length; i++) {
                if (round.options[i].key === key) return round.options[i];
            }
            return round.options[0];
        }

        _updateBriefing(state) {
            var round = this._currentRound(state);
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k){return k;};

            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.textContent = t(round.titleKey);

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = t(round.briefingKey);

            var select = document.getElementById('decisionInput');
            if (select) {
                var prev = state.decisions && state.decisions.choice ? state.decisions.choice : '';
                var matches = false;
                for (var i = 0; i < round.options.length; i++) {
                    if (round.options[i].key === prev) { matches = true; break; }
                }
                if (!matches) {
                    state.decisions.choice = round.options[0].key;
                    prev = round.options[0].key;
                }
                select.innerHTML = '';
                for (var j = 0; j < round.options.length; j++) {
                    var opt = round.options[j];
                    var optionEl = document.createElement('option');
                    optionEl.value = opt.key;
                    optionEl.textContent = t(opt.labelKey);
                    if (opt.key === prev) optionEl.selected = true;
                    select.appendChild(optionEl);
                }
                this._updateDetail(state, round);
                var self = this;
                select.onchange = function() {
                    state.decisions.choice = select.value;
                    self._updateDetail(state, round);
                };
            }

            var stamp = document.getElementById('greenwashStamp');
            if (stamp) {
                if (state.domainState.flags && state.domainState.flags.greenwash_exposed) {
                    stamp.textContent = t('stamp_greenwash');
                    stamp.style.display = 'block';
                } else if (state.domainState.flags && state.domainState.flags.sourcing_exposed) {
                    stamp.textContent = t('stamp_sourcing');
                    stamp.style.display = 'block';
                } else if (state.domainState.flags && state.domainState.flags.coverup_exposed) {
                    stamp.textContent = t('stamp_coverup');
                    stamp.style.display = 'block';
                } else {
                    stamp.style.display = 'none';
                }
            }
        }

        _updateDetail(state, round) {
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k){return k;};
            var detailEl = document.getElementById('decisionDetail');
            if (!detailEl) return;
            var opt = this._findOption(round, state.decisions.choice);
            var profitDelta = opt.profit;
            var repDelta = opt.reputation;
            var compassDelta = opt.compass;
            var sign = function(v) { return v > 0 ? '+' : ''; };
            var fmtProfit = sign(profitDelta) + '£' + Math.abs(profitDelta).toLocaleString();
            if (profitDelta < 0) fmtProfit = '−£' + Math.abs(profitDelta).toLocaleString();
            var parts = [
                '<strong>' + t(opt.detailKey) + '</strong>',
                t('est_impact') + ': ' + t('profit_short') + ' ' + fmtProfit +
                ' · ' + t('reputation_short') + ' ' + sign(repDelta) + repDelta +
                ' · ' + t('compass_short') + ' ' + sign(compassDelta) + compassDelta
            ];
            detailEl.innerHTML = parts.join('<br>');
        }

        validateDecisions(decisions) {
            var state = window.mySimulation.state;
            this._updateBriefing(state);
            var select = document.getElementById('decisionInput');
            if (select) decisions.choice = select.value;
            var round = this._currentRound(state);
            var valid = false;
            for (var i = 0; i < round.options.length; i++) {
                if (round.options[i].key === decisions.choice) { valid = true; break; }
            }
            if (!valid) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('decision_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        _applyDelayedConsequences(state, currentRoundIdx) {
            var flags = state.domainState.flags || {};
            var applied = state.domainState.appliedDelays || {};
            var repApplied = 0, compApplied = 0;
            var exposedStamp = null;
            for (var flagName in DELAYED) {
                if (!DELAYED.hasOwnProperty(flagName)) continue;
                var rule = DELAYED[flagName];
                if (flags[flagName] && !applied[flagName] && currentRoundIdx >= rule.appliesInRound) {
                    state.domainState.reputation = Math.max(0, Math.min(100, state.domainState.reputation + rule.reputation));
                    state.domainState.compass = Math.max(-100, Math.min(100, state.domainState.compass + rule.compass));
                    repApplied += rule.reputation;
                    compApplied += rule.compass;
                    applied[flagName] = true;
                    if (flagName === 'greenwash') flags.greenwash_exposed = true;
                    if (flagName === 'sourcing_risk') flags.sourcing_exposed = true;
                    if (flagName === 'coverup') flags.coverup_exposed = true;
                    exposedStamp = rule.stampKey;
                }
            }
            state.domainState.flags = flags;
            state.domainState.appliedDelays = applied;
            return { rep: repApplied, compass: compApplied, stamp: exposedStamp };
        }

        calculateResults(state) {
            var round = this._currentRound(state);
            var opt = this._findOption(round, state.decisions.choice);
            var t = window.mySimulation.t.bind(window.mySimulation);

            var profitBefore = state.domainState.profit;
            var repBefore = state.domainState.reputation;
            var compassBefore = state.domainState.compass;

            state.domainState.profit = profitBefore + opt.profit;
            state.domainState.reputation = Math.max(0, Math.min(100, repBefore + opt.reputation));
            state.domainState.compass = Math.max(-100, Math.min(100, compassBefore + opt.compass));

            if (opt.ethical) state.domainState.ethicalCount += 1;
            else state.domainState.unethicalCount += 1;

            if (opt.flag) {
                if (!state.domainState.flags) state.domainState.flags = {};
                state.domainState.flags[opt.flag] = true;
            }

            var delayed = this._applyDelayedConsequences(state, state.currentPeriod);

            if (round.id === 'csr_report') {
                var ethical = state.domainState.ethicalCount;
                var gw = state.domainState.flags && state.domainState.flags.greenwash;
                var coherenceBonus = 0;
                var coherenceCompass = 0;
                var coherenceNote = '';
                if (opt.key === 'friedman' && ethical <= 1) {
                    coherenceBonus = 4; coherenceCompass = 3; coherenceNote = t('coherence_honest_friedman');
                } else if (opt.key === 'friedman' && ethical >= 3) {
                    coherenceBonus = -10; coherenceCompass = -12; coherenceNote = t('coherence_incoherent_friedman');
                } else if (opt.key === 'full_csr' && !gw && ethical >= 3) {
                    coherenceBonus = 6; coherenceCompass = 5; coherenceNote = t('coherence_earned_fullcsr');
                } else if (opt.key === 'full_csr' && (gw || ethical <= 1)) {
                    coherenceBonus = -14; coherenceCompass = -18; coherenceNote = t('coherence_hollow_fullcsr');
                } else if (opt.key === 'authentic') {
                    coherenceBonus = 6; coherenceCompass = 6; coherenceNote = t('coherence_authentic');
                } else if (opt.key === 'balanced') {
                    coherenceBonus = 2; coherenceCompass = 2; coherenceNote = t('coherence_balanced');
                }
                state.domainState.reputation = Math.max(0, Math.min(100, state.domainState.reputation + coherenceBonus));
                state.domainState.compass = Math.max(-100, Math.min(100, state.domainState.compass + coherenceCompass));
                state.domainState.coherenceNote = coherenceNote;
                state.domainState.coherenceRep = coherenceBonus;
                state.domainState.coherenceCompass = coherenceCompass;
            }

            state.domainState.profitHistory.push(state.domainState.profit);
            state.domainState.reputationHistory.push(state.domainState.reputation);
            state.domainState.compassHistory.push(state.domainState.compass);
            state.domainState.decisionHistory.push({
                round: round.id,
                optionKey: opt.key,
                ethical: !!opt.ethical
            });

            // v1.1.0: persist a normalized, gradable 0-100 score + performance so the
            // reporting layer records a real score/timeline (previously null — neither
            // results.score nor domainState.performance.overallScore existed).
            var _rp = state.domainState.decisionHistory.length || 1;
            var _sg = this._computeScore(state.domainState, _rp);
            state.domainState.score = _sg.overallScore;
            state.domainState.performance = { overallScore: _sg.overallScore, grade: _sg.grade, stars: _sg.stars };

            var panel = document.getElementById('stakeholderPanel');
            if (panel) panel.style.display = 'block';
            var shMap = { shareholders: 'shShareholders', employees: 'shEmployees', customers: 'shCustomers', community: 'shCommunity' };
            for (var sh in shMap) {
                if (!shMap.hasOwnProperty(sh)) continue;
                var el = document.getElementById(shMap[sh]);
                if (!el) continue;
                var v = opt.sh[sh];
                el.textContent = t('reaction_' + (v === -2 ? 'vn' : v === -1 ? 'n' : v === 0 ? 'z' : v === 1 ? 'p' : 'vp'));
                el.classList.remove('sh-pos', 'sh-neg', 'sh-neu');
                if (v > 0) el.classList.add('sh-pos');
                else if (v < 0) el.classList.add('sh-neg');
                else el.classList.add('sh-neu');
            }

            var results = {
                period: state.currentPeriod,
                roundId: round.id,
                choiceKey: opt.key,
                choiceLabel: t(opt.labelKey),
                profitDelta: opt.profit,
                reputationDelta: opt.reputation + delayed.rep,
                compassDelta: opt.compass + delayed.compass,
                profit: state.domainState.profit,
                reputation: state.domainState.reputation,
                compass: state.domainState.compass,
                delayedTriggered: delayed.stamp || null,
                ethical: !!opt.ethical,
                score: _sg.overallScore,
                overallScore: _sg.overallScore,
                stars: _sg.stars
            };

            var self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
            }, 500);

            return results;
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('profitDisplay', 'domainState.profit',
                (v) => '£' + Math.round(v).toLocaleString());
            uiManager.bind('reputationDisplay', 'domainState.reputation',
                (v) => Math.round(v) + ' / 100');
            uiManager.bind('compassDisplay', 'domainState.compass',
                (v) => (v > 0 ? '+' : '') + Math.round(v));
        }

