        getHint(state, results) {
            if (!results) return null;
            if (results.delayedTriggered === 'stamp_greenwash') return window.mySimulation.t('hint_greenwash_exposed');
            if (results.delayedTriggered === 'stamp_sourcing') return window.mySimulation.t('hint_sourcing_exposed');
            if (results.delayedTriggered === 'stamp_coverup') return window.mySimulation.t('hint_coverup_exposed');
            if (results.roundId === 'csr_report' && state.domainState.coherenceRep < 0) return window.mySimulation.t('hint_incoherent');
            if (results.roundId === 'csr_report' && state.domainState.coherenceRep > 0) return window.mySimulation.t('hint_coherent');
            if (results.compass < -30) return window.mySimulation.t('hint_low_compass');
            if (results.reputation < 25) return window.mySimulation.t('hint_low_reputation');
            if (results.ethical) return window.mySimulation.t('hint_ethical');
            return window.mySimulation.t('hint_trade_off');
        }

